html,
body {
	margin: 0;
	padding: 0;
	overflow: hidden;
}


.loadingclass{
	height: 100vh;
	width: 100vw;
	position: absolute;
	font-family: Arial;
	text-align: center;
	padding-top: 20%;
	font-size: 9em;
	animation: pulse 1s infinite;


}


@keyframes pulse {
  0% {
    background-color: black;
		color: white;


  }
  100% {
    background-color: white;
		color: black;



  }
}

/* Auto-hidden controls */
input, select, button, textarea, label, fieldset,
.dg, .lil-gui, .qs_main, .opc-container, .opc-gui, .quicksettings, .p5DomElement {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    pointer-events: none !important;
    position: absolute !important;
    left: -9999px !important;
    top: -9999px !important;
    width: 0px !important;
    height: 0px !important;
}
